const PHOTO_SRC = "data:image/jpeg;base64,";

function esc(s){return s.replace(/&/g,"&amp;").replace(/</g,"&lt;");}

function cmdLink(href){
  if(href === "#") return "";
  let cmd;
  if(href.includes("github.com")){
    cmd = "$ git clone " + href.replace("https://github.com/","git@github.com:") + ".git";
  } else {
    cmd = "$ open " + href;
  }
  return `<div class="cmdline mono" onclick="window.open('${href}','_blank')">${esc(cmd)}<span class="cmd-cursor"></span></div>`;
}

