function renderProjectDetail(id){
  const p = PROJECTS.find(x => x.id === id);
  if(!p) return `<p>Project not found.</p><span class="back" data-go="projects">&larr; back to projects</span>`;
  const points = p.points.map(pt => `<li>${esc(pt)}</li>`).join("");
  return `
    <span class="back" data-go="projects">&larr; back to projects</span>
    <div class="detail">
      <div class="cat">${esc(p.cat)}</div>
      <h1>${esc(p.title)}</h1>
      <p style="color:var(--muted);margin-top:10px;">${esc(p.summary)}</p>
      <ul>${points}</ul>
      ${cmdLink(p.href)}
    </div>
  `;
}

