const ROUTES = {
  home: renderHome,
  about: renderAbout,
  projects: renderProjects,
  certifications: renderCerts,
  contact: renderContact
};

function render(){
  let hash = (location.hash || "#home").slice(1);
  const app = document.getElementById("app");

  let html;
  if(hash.startsWith("project-")){
    html = renderProjectDetail(hash.replace("project-",""));
  } else if(ROUTES[hash]){
    html = ROUTES[hash]();
  } else {
    hash = "home";
    html = renderHome();
  }
  app.innerHTML = html;

  const certificateViewer = app.querySelector(".certificate-viewer");
  if(certificateViewer){
    const certificateImage = certificateViewer.querySelector("img");
    app.querySelectorAll("[data-certificate-index]").forEach(button=>{
      button.addEventListener("click",()=>{
        const certificate = CERTS[Number(button.dataset.certificateIndex)];
        if(!certificate) return;
        certificateImage.src = certificate.img;
        certificateImage.alt = certificate.title;
        certificateViewer.showModal();
      });
    });
    certificateViewer.querySelector(".certificate-viewer-close").addEventListener("click",()=>{
      certificateViewer.close();
    });
    certificateViewer.addEventListener("click",event=>{
      if(event.target === certificateViewer) certificateViewer.close();
    });
  }

  document.querySelectorAll(".navlinks a").forEach(a=>{
    a.classList.toggle("active", a.dataset.go === hash || (hash.startsWith("project-") && a.dataset.go === "projects"));
  });

  document.querySelectorAll("[data-go]").forEach(el=>{
    el.onclick = () => { location.hash = "#" + el.dataset.go; };
  });

  window.scrollTo({top:0, behavior:"instant"});
}

window.addEventListener("hashchange", render);
window.addEventListener("DOMContentLoaded", render);

// --- light matrix rain, home hero only, re-inits every time home renders ---
function initRain(){
  const canvas = document.getElementById("rain");
  if(!canvas) return;
  const ctx = canvas.getContext("2d");
  const chars = "01アイウエオカキクケコ<>/{}#$";
  const fontSize = 14;
  let cols, drops;

  function resize(){
    canvas.width = canvas.offsetWidth;
    canvas.height = canvas.offsetHeight;
    cols = Math.floor(canvas.width / fontSize);
    drops = new Array(cols).fill(0).map(()=>Math.random() * -30);
  }
  resize();

  const reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  function draw(){
    if(!document.body.contains(canvas)) { clearInterval(timer); return; }
    ctx.fillStyle = "rgba(6,16,10,0.15)";
    ctx.fillRect(0,0,canvas.width,canvas.height);
    ctx.font = fontSize + "px monospace";
    for(let i=0;i<cols;i++){
      const ch = chars[Math.floor(Math.random()*chars.length)];
      ctx.fillStyle = "#36D97A";
      ctx.fillText(ch, i*fontSize, drops[i]*fontSize);
      if(drops[i]*fontSize > canvas.height && Math.random() > 0.975) drops[i] = 0;
      drops[i]++;
    }
  }
  let timer;
  if(!reduceMotion){ timer = setInterval(draw, 70); }
}
